class Solution {
  public long maxPoints(int[] technique1, int[] technique2, int k) {
    int n = technique1.length;
    long total = 0;
    int[] gain = new int[n];
    for (int i = 0; i < n; i++) {
      total += technique2[i];
      gain[i] = technique1[i] - technique2[i];
    }
    java.util.Arrays.sort(gain);
    for (int i = n - 1; i >= 0; i--) {
      if (n - 1 - i < k || gain[i] > 0) total += gain[i];
    }
    return total;
  }
}
